  }
  .move-btn:hover { background: #2b2f38; }
  .move-btn[disabled] { opacity: 0.4; cursor: not-allowed; }
  .add-form {
    display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; align-items: center;
  }
  .add-form input[type="text"] {
    flex: 1; min-width: 180px; padding: 8px 12px; border-radius: 999px;
    border: 1px solid var(--border); background: var(--panel-2); color: var(--text);
    font: inherit;
  }
  .add-form input::placeholder { color: var(--muted); }
  .footer { margin-top: 24px; color: var(--muted); font-size: 12px; line-height: 1.6; }
  .toast {
    position: fixed; bottom: 16px; left: 50%; transform: translateX(-50%);
    background: #1f2129; border: 1px solid var(--border); color: var(--text);
    padding: 8px 14px; border-radius: 999px; font-size: 13px; box-shadow: 0 8px 24px rgba(0,0,0,0.4);
    opacity: 1; transition: opacity 0.2s;
  }
  .toast.hide { opacity: 0; pointer-events: none; }

  @media (max-width: 1000px) {
    .boards { grid-template-columns: repeat(2, 1fr); }
    .board[data-tier="무"] { order: -1; min-height: 120px; }
  }
  @media (max-width: 620px) {
    .boards { grid-template-columns: 1fr; }
    .toolbar { flex-direction: column; align-items: stretch; }
    .count { margin-left: 0; text-align: right; }
  }
</style>
