<body>
<div class="wrap">
  <header>
    <h1>내 영화 티어리스트</h1>
    <div class="meta">내 브라우저에서만 저장됩니다</div>
  </header>

  <div class="toolbar">
    <button id="resetBtn" type="button">처음으로</button>
    <span class="count" id="countLabel">0개 분류됨 · 0개 미분류</span>
  </div>

  <div class="msg" id="msg" role="status" aria-live="polite"></div>

  <div class="boards" id="boards">
    <!-- S -->
    <section class="board" data-tier="S" aria-label="S 등급">
      <div class="board-title">
        <div class="board-head">
          <span class="tier-pill tier-S">S</span>
          <span class="board-count" id="count-S">0</span>
        </div>
      </div>
      <div class="cards" id="cards-S" data-tier="S" aria-live="polite"></div>
    </section>
    <!-- A -->
    <section class="board" data-tier="A" aria-label="A 등급">
      <div class="board-title">
        <div class="board-head">
          <span class="tier-pill tier-A">A</span>
          <span class="board-count" id="count-A">0</span>
        </div>
      </div>
      <div class="cards" id="cards-A" data-tier="A" aria-live="polite"></div>
    </section>
    <!-- B -->
    <section class="board" data-tier="B" aria-label="B 등급">
      <div class="board-title">
        <div class="board-head">
          <span class="tier-pill tier-B">B</span>
          <span class="board-count" id="count-B">0</span>
        </div>
      </div>
      <div class="cards" id="cards-B" data-tier="B" aria-live="polite"></div>
    </section>
    <!-- C -->
    <section class="board" data-tier="C" aria-label="C 등급">
      <div class="board-title">
        <div class="board-head">
          <span class="tier-pill tier-C">C</span>
          <span class="board-count" id="count-C">0</span>
        </div>
      </div>
      <div class="cards" id="cards-C" data-tier="C" aria-live="polite"></div>
    </section>
    <!-- 무 -->
    <section class="board" data-tier="무" aria-label="미분류">
      <div class="board-title">
        <div class="board-head">
          <span class="tier-pill tier-무">무</span>
          <span class="board-count" id="count-무">0</span>
        </div>
        <div class="add-form">
          <input type="text" id="addInput" placeholder="영화 제목을 입력하세요 (80자 이내)" aria-label="영화 제목 입력" maxlength="80">
          <input type="submit" id="addSubmit" value="추가">
        </div>
      </div>
      <div class="cards" id="cards-무" data-tier="무" aria-live="polite"></div>
    </section>
  </div>

  <footer class="footer">
    • 카드를 선택 후 등급 이동 버튼을 누르거나, 카드를 끌어 원하는 칸으로 이동하세요.<br>
    • 새 영화는 미분류 아래 입력창에서 추가하세요. 중복·빈 입력·80자 초과는 거부하고 이유를 표시합니다.<br>
    • 저장소는 같은 브라우저·같은 파일 경로에서만 기대됩니다. 차단되면 안내가 표시됩니다.
  </footer>
</div>

<div class="toast" id="toast" role="alert" aria-live="assertive"></div>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "movie_tierlist_v1";
  var TIERS = ["S", "A", "B", "C", "무"];
  var DEFAULT_MOVIES = ["기생충", "인터스텔라", "라라랜드", "센과 치히로의 행방불명", "어벤져스: 엔드게임", "범죄도시", "타이타닉", "토이 스토리"];
  var MAX_LEN = 80;

  var state = {
    movies: [], // [{id, title, tier}]
    selectedId: null
  };

  var els = {
    boards: document.getElementById("boards"),
    addInput: document.getElementById("addInput"),
    addSubmit: document.getElementById("addSubmit"),
    msg: document.getElementById("msg"),
    countLabel: document.getElementById("countLabel"),
    resetBtn: document.getElementById("resetBtn"),
    toast: document.getElementById("toast")
  };

  // ---------- 저장소 ----------
  function loadState() {
    var raw = null;
    try {
      raw = localStorage.getItem(STORAGE_KEY);
    } catch (e) {
      raw = null;
    }
    if (!raw) return null;
    try {
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return null;
      for (var i = 0; i < parsed.length; i++) {
        var m = parsed[i];
        if (typeof m.id !== "string" || typeof m.title !== "string" || typeof m.tier !== "string") return null;
        if (TIERS.indexOf(m.tier) === -1) return null;
        if (m.title.length === 0) return null;
      }
      return parsed;
    } catch (e) {
      return null;
    }
  }

  function saveState(retry) {
    var data = JSON.stringify(state.movies);
    var failed = false;
    try {
      localStorage.setItem(STORAGE_KEY, data);
    } catch (e) {
      failed = true;
    }
    if (failed) {
      showMsg("저장에 실패했습니다. 추가된 영화는 이 화면에서만 유지됩니다. 새로고침 후 다시 시도해 주세요.", true);
      return false;
    }
    return true;
  }

  // ---------- 메시지 ----------
  var msgTimer = null;
  function showMsg(text, isError) {
    els.msg.textContent = text || "";
    if (msgTimer) clearTimeout(msgTimer);
    msgTimer = setTimeout(function () {
      els.msg.textContent = "";
    }, 4500);
  }

  var toastTimer = null;
  function showToast(text) {
    els.toast.textContent = text;
    els.toast.classList.remove("hide");
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      els.toast.classList.add("hide");
    }, 2200);
  }

  // ---------- 렌더링 ----------
  function render() {
    for (var i = 0; i < TIERS.length; i++) {
      var tier = TIERS[i];
      var cards = state.movies.filter(function (m) { return m.tier === tier; });
      var list = document.getElementById("cards-" + tier);
      var count = document.getElementById("count-" + tier);
      count.textContent = cards.length;

      list.innerHTML = "";
      if (cards.length === 0) {
        var empty = document.createElement("div");
        empty.className = "drop-empty";
        empty.textContent = (tier === "무") ? "추가한 영화가 없습니다." : "아직 분류된 영화가 없습니다.";
        list.appendChild(empty);
      } else {
        for (var j = 0; j < cards.length; j++) {
          list.appendChild(buildCard(cards[j]));
        }
      }
    }

    var classified = state.movies.filter(function (m) { return m.tier !== "무"; }).length;
    var unclassified = state.movies.filter(function (m) { return m.tier === "무"; }).length;
    els.countLabel.textContent = classified + "개 분류됨 · " + unclassified + "개 미분류";

    updateSelectedState();
  }

  function buildCard(movie) {
    var btnS = document.createElement("button");
    btnS.type = "button";
    btnS.className = "move-btn";
    btnS.textContent = "S로";
    btnS.setAttribute("aria-label", movie.title + "을 S 등급으로 이동");
    btnS.addEventListener("click", function (e) {
      e.stopPropagation();
      moveTo(movie.id, "S");
    });

    var btnA = document.createElement("button");
    btnA.type = "button";
    btnA.className = "move-btn";
    btnA.textContent = "A로";
    btnA.setAttribute("aria-label", movie.title + "을 A 등급으로 이동");
    btnA.addEventListener("click", function (e) {
      e.stopPropagation();
      moveTo(movie.id, "A");
    });

    var btnB = document.createElement("button");
    btnB.type = "button";
    btnB.className = "move-btn";
    btnB.textContent = "B로";
    btnB.setAttribute("aria-label", movie.title + "을 B 등급으로 이동");
    btnB.addEventListener("click", function (e) {
      e.stopPropagation();
      moveTo(movie.id, "B");
    });

    var btnC = document.createElement("button");
    btnC.type = "button";
    btnC.className = "move-btn";
    btnC.textContent = "C로";
    btnC.setAttribute("aria-label", movie.title + "을 C 등급으로 이동");
    btnC.addEventListener("click", function (e) {
      e.stopPropagation();
      moveTo(movie.id, "C");
    });

    var card = document.createElement("div");
    card.className = "card";
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.setAttribute("aria-pressed", "false");
    card.setAttribute("aria-label", movie.title + ", 현재 " + movie.tier + " 등급, 선택하려면 Enter 또는 Space");
    card.setAttribute("draggable", "true");
    card.dataset.id = movie.id;

    var title = document.createElement("div");
    title.className = "card-title";
    title.textContent = movie.title;
    card.appendChild(title);

    var controls = document.createElement("div");
    controls.className = "card-controls";
    controls.appendChild(btnS);
    controls.appendChild(btnA);
    controls.appendChild(btnB);
    controls.appendChild(btnC);
    card.appendChild(controls);

    card.addEventListener("click", function () { selectCard(movie.id); });
    card.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        selectCard(movie.id);
      }
    });

    // drag
    card.addEventListener("dragstart", function (e) {
      e.dataTransfer.setData("text/plain", movie.id);
      e.dataTransfer.effectAllowed = "move";
      card.classList.add("dragging");
    });
    card.addEventListener("dragend", function () {
      card.classList.remove("dragging");
      clearDragOver();
    });

    // select highlight while dragging
    card.addEventListener("drag", function () {
      // noop
    });

    return card;
  }

  function updateSelectedState() {
    var all = document.querySelectorAll(".card");
    for (var i = 0; i < all.length; i++) {
      var c = all[i];
      var id = c.dataset.id;
      if (id === state.selectedId) {
        c.classList.add("selected");
        c.setAttribute("aria-pressed", "true");
      } else {
        c.classList.remove("selected");
        c.setAttribute("aria-pressed", "false");
      }
    }
  }

  function selectCard(id) {
    if (state.selectedId === id) {
      state.selectedId = null;
    } else {
      state.selectedId = id;
    }
    updateSelectedState();
    if (state.selectedId) {
      showToast("선택됨");
    }
  }

  function clearDragOver() {
    var olds = document.querySelectorAll(".card.drag-over");
    for (var i = 0; i < olds.length; i++) olds[i].classList.remove("drag-over");
  }

  // ---------- 이동 ----------
  function moveTo(id, tier) {
    var movie = null;
    for (var i = 0; i < state.movies.length; i++) {
      if (state.movies[i].id === id) { movie = state.movies[i]; break; }
    }
    if (!movie) return;
    if (movie.tier === tier) {
      showMsg("이미 " + tier + " 등급입니다.");
      return;
    }
    movie.tier = tier;
    state.selectedId = null;
    if (!saveState(false)) {
      movie.tier = movie.tier; // keep change but warn
      render();
      return;
    }
    render();
    showToast(movie.title + " → " + tier);
  }

  function moveSelectedTo(tier) {
    if (!state.selectedId) {
      showMsg("이동할 영화를 먼저 선택하세요.");
      return;
    }
    moveTo(state.selectedId, tier);
  }

  // ---------- 드래그 타겟 ----------
  var boardEls = {};
  TIERS.forEach(function (tier) {
    var host = document.getElementById("cards-" + tier);
    boardEls[tier] = host;
    host.addEventListener("dragover", function (e) {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      host.classList.add("drag-over");
    });
    host.addEventListener("dragleave", function (e) {
      if (!host.contains(e.relatedTarget)) {
        host.classList.remove("drag-over");
      }
    });
    host.addEventListener("drop", function (e) {
      e.preventDefault();
      host.classList.remove("drag-over");
      var id = e.dataTransfer.getData("text/plain");
      if (!id) return;
      var movie = null;
      for (var i = 0; i < state.movies.length; i++) {
        if (state.movies[i].id === id) { movie = state.movies[i]; break; }
      }
      if (!movie) return;
      if (movie.tier === tier) {
        showMsg("이미 " + tier + " 등급입니다.");
        return;
      }
      movie.tier = tier;
      state.selectedId = id;
      if (!saveState(false)) {
        render();
        showMsg("이동은 반영되었으나 저장에 실패했습니다.");
        return;
      }
      render();
      showToast(movie.title + " → " + tier);
    });
  });

  // 전역 drag-over 정리
  document.addEventListener("dragover", function (e) { e.preventDefault(); });
  document.addEventListener("drop", function (e) { e.preventDefault(); });

  // ---------- 추가 ----------
  function addMovie(raw) {
    var title = String(raw).trim();
    if (title.length === 0) {
      showMsg("제목이 비어 있습니다. 영화 이름을 입력해 주세요.");
      return false;
    }
    if (title.length > MAX_LEN) {
      showMsg("제목이 " + MAX_LEN + "자를 초과합니다. 짧게 입력해 주세요.");
      return false;
    }
    for (var i = 0; i < state.movies.length; i++) {
      if (state.movies[i].title === title) {
        showMsg("이미 있는 영화입니다: " + title);
        return false;
      }
    }
    var id = "m_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8);
    state.movies.push({ id: id, title: title, tier: "무" });
    if (!saveState(false)) {
      render();
      showMsg("추가했으나 저장에 실패했습니다. 이 화면에서만 유지됩니다.");
      return true;
    }
    render();
    showToast(title + " 추가됨 (미분류)");
    return true;
  }

  function resetToDefault() {
    if (state.movies.length === 0) {
      // initialize
      state.movies = DEFAULT_MOVIES.map(function (t) { return { id: "d_" + t.replace(/[^a-zA-Z0-9가-힣]/g, "_"), title: t, tier: "무" }; });
      state.selectedId = null;
      saveState(true);
      render();
      showToast("초기 8개 영화가 미분류에 배치되었습니다.");
      return;
    }

    var countDefault = (function () {
      var n = 0;
      for (var i = 0; i < state.movies.length; i++) {
        if (DEFAULT_MOVIES.indexOf(state.movies[i].title) !== -1) n++;
      }
      return n;
    })();

    if (countDefault === 0) {
      showMsg("초기 영화와 겹치는 항목이 없어 되돌릴 기준이 없습니다.");
      return;
    }

    var ok = window.confirm("처음으로 버튼을 누르면 현재 분류가 초기화되고 최초 8개 영화만 미분류로 남습니다. 계속하시겠습니까?");
    if (!ok) {
      showMsg("취소했습니다. 현재 상태를 유지합니다.");
      return;
    }

    // 처음으로: 최초 8개를 미분류로, 나머지는 제거
    var keep = [];
    var seen = {};
    for (var i = 0; i < DEFAULT_MOVIES.length; i++) {
      var t = DEFAULT_MOVIES[i];
      if (seen[t]) continue;
      seen[t] = true;
      var found = null;
      for (var j = 0; j < state.movies.length; j++) {
        if (state.movies[j].title === t) { found = state.movies[j]; break; }
      }
      if (found) {
        found.tier = "무";
        keep.push(found);
      } else {
